    font-weight: 600;
    letter-spacing: -0.015em;
    color: var(--text);
    margin-bottom: 0.2rem;
}

.bento-tile-desc {
    font-size: var(--type-label-lg);
    color: var(--text-muted);
    line-height: 1.4;
