        @PaymentId, @PaymentIdentifier, @AppPaymentIdParam, @Amount, @CurrencyParam, @SubMerchantRrnParam,
        @StatusParam, @AcmeTransactionUuid, @SubMerchantId, @CreatedBy, @UpdatedBy);

